func getSubpathFromWorkingDirectory(wd, path string) string {
	subpath := path
	if filepath.IsAbs(subpath) {
		var err error
		subpath, err = filepath.Rel(wd, path)
		if err != nil || strings.HasPrefix(subpath, "..") {
			oktetoLog.Info("could not retrieve subpath")
			subpath = filepath.Base(path)
		}
	}
	return subpath
}

